try { jsonData = pm.response.json(); } catch (e) { jsonData = {}; }
const pick = (...paths) => {
  for (const p of paths) {
    const value = p.split(".").reduce((acc, key) => acc && acc[key], jsonData);
    if (value !== undefined && value !== null && value !== "") return value;
  }
};
const accessToken = pick("access", "access_token", "accessToken", "token", "data.access", "data.access_token", "data.accessToken", "data.token");
if (accessToken) pm.collectionVariables.set("accessToken", accessToken);
const refreshToken = pick("refresh", "refresh_token", "refreshToken", "data.refresh", "data.refresh_token", "data.refreshToken");
if (refreshToken) pm.collectionVariables.set("refreshToken", refreshToken);
const id = pick("id", "_id", "data.id", "data._id", "data.user.id", "data.customer.id", "data.account.id", "data.transaction.id");
if (id) pm.collectionVariables.set("resourceId", id);
