// Auto-fetch a fresh hashDigest before login
const baseUrl = pm.collectionVariables.get("baseUrl") || pm.environment.get("baseUrl");
const xApiKey = pm.collectionVariables.get("xApiKey") || pm.environment.get("xApiKey");
const testEmail = pm.collectionVariables.get("testEmail") || pm.environment.get("testEmail");
const password = pm.collectionVariables.get("password") || pm.environment.get("password");
const deviceId = pm.collectionVariables.get("deviceId") || pm.environment.get("deviceId");

pm.sendRequest({
    url: baseUrl + "/api/v1/users/encrypt-payload",
    method: "POST",
    header: {
        "X-Api-Key": xApiKey,
        "Content-Type": "application/json",
        "Accept": "application/json"
    },
    body: {
        mode: "raw",
        raw: JSON.stringify({
            email: testEmail,
            password: password,
            device_id: deviceId
        })
    }
}, function (err, res) {
    if (err) {
        console.error("Encrypt Login failed:", err);
        throw new Error("Pre-request: Encrypt Login request failed - " + err);
    }
    if (res.code !== 200) {
        console.error("Encrypt Login returned non-200:", res.code, res.text());
        throw new Error("Pre-request: Encrypt Login returned status " + res.code);
    }
    const json = res.json();
    const hashDigest = json && json.data && json.data.hash_digest;
    if (!hashDigest) {
        console.error("Encrypt Login response missing data.hash_digest:", res.text());
        throw new Error("Pre-request: hash_digest not found in Encrypt Login response");
    }
    pm.collectionVariables.set("hashDigest", hashDigest);
    console.log("hashDigest refreshed successfully");
});

